#include <bits/stdc++.h>
using namespace std;

long long atMostKDistinct(vector<int>& nums, int k) {
    unordered_map<int, int> count;
    long long start = 0, total = 0;
    for (int i = 0; i < (int)nums.size(); ++i) {
        ++count[nums[i]];
        while ((int)count.size() > k) {
            if (--count[nums[start]] == 0) count.erase(nums[start]);
            ++start;
        }
        total += i - start + 1;
    }
    return total;
}

int subarraysWithKDistinct(vector<int>& nums, int k) {
    return (int)(atMostKDistinct(nums, k) - atMostKDistinct(nums, k - 1));
}

