import java.util.HashMap;
import java.util.Map;

class Solution {
    private long atMostKDistinct(int[] nums, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        long start = 0, total = 0;
        for (int i = 0; i < nums.length; ++i) {
            count.merge(nums[i], 1, Integer::sum);
            while (count.size() > k) {
                int left = nums[(int) start];
                if (count.merge(left, -1, Integer::sum) == 0) count.remove(left);
                ++start;
            }
            total += i - start + 1;
        }
        return total;
    }

    public int subarraysWithKDistinct(int[] nums, int k) {
        return (int)(atMostKDistinct(nums, k) - atMostKDistinct(nums, k - 1));
    }
}
